+// Sites (kitchens). Every location belongs to one site; a batch is at the
+// site of its location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** A predicate telling whether a batch (or anything with `location`) is at `site`; every one when `site` is undefined. */
+export function atSite(store, site) {
+  if (site === undefined) return () => true;
+  const siteOf = new Map(store.data.locations.map((l) => [l.id, l.site ?? DEFAULT_SITE]));
+  return (x) => (siteOf.get(x.location) ?? DEFAULT_SITE) === site;
+}
