+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts 3 l of milk (item 2) into the annex fridge as batch `id`.
+function stockAnnex(store, id = 100) {
+  store.data.batches.push({ id, itemId: 2, lot: "AX-1", qty: 3, receivedOn: "2026-10-27", expires: "2026-10-30", location: "annex-fridge" });
+}
+
+test("the seed has two sites", async () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+  assert.ok(store.data.locations.filter((l) => l.id !== "annex-fridge").every((l) => l.site === "main"));
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("stock on hand and batches only see the request's site", async () => {
+  const { handle, store } = app();
+  stockAnnex(store);
+  const main = (await handle({ path: "/items" })).body.find((i) => i.id === 2);
+  assert.equal(main.onHand, 10);
+  const annex = (await handle({ path: "/items/2", headers: ANNEX })).body;
+  assert.equal(annex.onHand, 3);
+  assert.deepEqual(annex.batches.map((b) => b.id), [100]);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [100]);
+  assert.equal((await handle({ path: "/batches/100" })).status, 404);
+  assert.equal((await handle({ path: "/batches/3", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/3/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(res.body.error.code, "not_enough_stock");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("alerts and stock value only see the request's site", async () => {
+  const { handle, store } = app();
+  stockAnnex(store);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [100]);
+  assert.ok(alerts.lowStock.some((l) => l.itemId === 1 && l.qty === 0));
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 3 * 129);
+  const main = (await handle({ path: "/reports/stock-value" })).body;
+  assert.equal(main.lines.find((l) => l.itemId === 2).qty, 10);
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle, store } = app();
+  stockAnnex(store);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 100, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: 3, counted: 2 } })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: 100, counted: 2 } });
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  const res = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.deepEqual(res.body.lines, [{ batchId: 100, expected: 3, counted: 2, diff: -1 }]);
+});
+
